import React, { useState } from 'react';

// Create the ToggleVisibility component here
const ToggleVisibility = () => {
  // Add useState hook here
  const [isVisible, setIsVisible] = useState(true);

  // Define toggleVisibility function here
  const toggleVisibility = () => {
    setIsVisible(!isVisible);
  };

  return (
    <div>
      <h1>Toggle Visibility Widget</h1>
      {isVisible ? <p>This content is now visible!</p> : null}

    </div>
  );
};

